body {
  margin: 0;
  font-family: system-ui, sans-serif;
  color: #1c1e22;
}

main {
  max-width: 960px;
  margin: 0 auto;
  padding: 24px;
}

/* The books list: a grid of cards. */
.books {
  list-style: none;
  padding: 0;
  display: grid;
  gap: 32px;
  grid-template-columns: repeat(auto-fill, minmax(220px, 1fr));
}

.book-link {
  color: inherit;
  text-decoration: none;
}

.book-cover {
  width: 100%;
  height: auto;
  border-radius: 6px;
}

.book-title {
  margin: 12px 0 4px;
  font-size: 20px;
}

.book-subtitle {
  margin: 0;
}

.book-meta {
  margin: 4px 0 0;
  color: #666;
  font-size: 14px;
}

/* One book. */
.book-page {
  display: grid;
  gap: 32px;
  grid-template-columns: 240px 1fr;
}

.book-page[hidden] {
  display: none;
}

.book-page-cover {
  width: 100%;
  height: auto;
  border-radius: 6px;
}

.button {
  display: inline-block;
  padding: 10px 18px;
  border-radius: 6px;
  background: #00b295;
  color: #fff;
  text-decoration: none;
}

@media (max-width: 640px) {
  .book-page {
    grid-template-columns: 1fr;
  }
}

import { getBook, plainText } from './wordpress.js';

const status = document.getElementById('status');
const slug = new URLSearchParams(location.search).get('slug');

try {
  const book = slug ? await getBook(slug) : null;
  if (!book) throw new Error('No book with that address.');

  const f = book.acf;
  const title = plainText(book.title.rendered);

  document.title = title;
  document.getElementById('title').textContent = title;
  document.getElementById('subtitle').textContent = f.subtitle ?? '';
  document.getElementById('meta').textContent = [f.book_author, f.pages ? `${Number(f.pages)} pages` : '']
    .filter(Boolean).join(' · ');

  // The post body, written in the WordPress editor. It is HTML from your own site.
  document.getElementById('content').innerHTML = book.content.rendered;

  const cover = document.getElementById('cover');
  if (f.cover_image?.url) {
    cover.src = f.cover_image.url;
    cover.alt = f.cover_image.alt;
  }
  else cover.remove();

  if (f.buy_url) {
    const buy = document.getElementById('buy');
    buy.href = f.buy_url;
    buy.hidden = false;
  }

  document.getElementById('book').hidden = false;
  status.remove();
} catch (error) {
  status.textContent = error.message;
}

import { getBooks, getGenres, plainText } from './wordpress.js';

const list = document.getElementById('books');
const status = document.getElementById('status');
const card = document.getElementById('book-card');

try {
  // Both requests run at the same time.
  const [books, genres] = await Promise.all([getBooks(), getGenres()]);
  const genreName = new Map(genres.map((g) => [g.id, g.name]));

  for (const book of books) {
    const f = book.acf;
    const item = card.content.cloneNode(true);

    item.querySelector('.book-link').href = `book.html?slug=${encodeURIComponent(book.slug)}`;
    item.querySelector('.book-title').textContent = plainText(book.title.rendered);
    item.querySelector('.book-subtitle').textContent = f.subtitle ?? '';
    item.querySelector('.book-meta').textContent = [
      f.book_author,
      f.pages ? `${Number(f.pages)} pages` : '',
      book.genre.map((id) => genreName.get(id)).join(', '),
    ].filter(Boolean).join(' · ');

    const cover = item.querySelector('.book-cover');
    if (f.cover_image?.url) cover.src = f.cover_image.sizes?.medium_large ?? f.cover_image.url;
    else cover.remove();

    list.append(item);
  }
  status.remove();
} catch (error) {
  status.textContent = `Could not load the books: ${error.message}`;
}

// Every request to WordPress goes through this file, so the pages never build a
// REST URL by hand.
import { WP_URL } from './config.js';

// Ask only for what the pages use: smaller responses, faster pages.
// acf_format=standard makes ACF return each field in its "Return Format": the
// cover image as an object with its URL, size and alt text instead of a bare ID.
const BOOK_QUERY = '_fields=id,slug,title,excerpt,content,genre,acf&acf_format=standard';

async function wp(path) {
  const res = await fetch(`${WP_URL}/wp-json${path}`);
  if (!res.ok) {
    throw new Error(`WordPress returned ${res.status} for ${path}`);
  }
  return res.json();
}

export function getBooks() {
  return wp(`/wp/v2/book?${BOOK_QUERY}&per_page=100`);
}

export async function getBook(slug) {
  const books = await wp(`/wp/v2/book?slug=${encodeURIComponent(slug)}&${BOOK_QUERY}`);
  return books[0] ?? null;
}

export function getGenres() {
  return wp('/wp/v2/genre?_fields=id,name,slug&per_page=100');
}

// WordPress returns titles as HTML ("Tom &amp; Jerry"); turn that into plain text.
export function plainText(html) {
  return new DOMParser().parseFromString(html, 'text/html').body.textContent;
}
